def fill_slugs(apps, schema_editor):
    """Produtos e categorias que já existiam ganham o slug pelo nome (repetido ganha -2, -3...)."""
    from django.utils.text import slugify

    for name in ("Product", "Category"):
        model = apps.get_model("starrp", name)
        taken = set()
        for row in model._base_manager.filter(deleted_at__isnull=True).order_by("created_at"):
            base = (slugify(row.name) or "item")[:170]
            slug, n = base, 2
            while (row.account_id, slug) in taken:
                slug, n = f"{base}-{n}", n + 1
            taken.add((row.account_id, slug))
            model._base_manager.filter(pk=row.pk).update(slug=slug)


